CREATE TABLE {{SCHEMA}}.repos (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, url text UNIQUE NOT NULL, owner text NOT NULL, name text NOT NULL, default_branch text, indexed_sha text, status text NOT NULL DEFAULT 'registered' CHECK (status IN ('registered','indexing','ready','failed')), last_error text, last_checked_at timestamptz, last_queried_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE {{SCHEMA}}.files (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, repo_id bigint NOT NULL REFERENCES {{SCHEMA}}.repos(id) ON DELETE CASCADE, path text NOT NULL, file_hash text NOT NULL, language text, size_bytes bigint NOT NULL CHECK (size_bytes >= 0), last_seen_sha text NOT NULL, UNIQUE(repo_id,path));
CREATE TABLE {{SCHEMA}}.chunks (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, repo_id bigint NOT NULL REFERENCES {{SCHEMA}}.repos(id) ON DELETE CASCADE, file_id bigint NOT NULL REFERENCES {{SCHEMA}}.files(id) ON DELETE CASCADE, symbol text, symbol_type text NOT NULL CHECK (symbol_type IN ('function','method','class','class_skeleton','module_header','doc_section','config','text_block')), parent_symbol text, start_line integer NOT NULL CHECK (start_line >= 1), end_line integer NOT NULL CHECK (end_line >= start_line), text text NOT NULL, content_hash text NOT NULL, search_text text NOT NULL, fts tsvector GENERATED ALWAYS AS (to_tsvector('simple', search_text)) STORED, token_count integer NOT NULL CHECK (token_count >= 0), chunker_version text NOT NULL, embedder_version text, embedding extensions.vector({{EMBEDDING_DIM}}), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX chunks_repo_idx ON {{SCHEMA}}.chunks(repo_id); CREATE INDEX chunks_file_idx ON {{SCHEMA}}.chunks(file_id); CREATE INDEX chunks_fts_idx ON {{SCHEMA}}.chunks USING GIN(fts); CREATE INDEX chunks_embedding_reuse_idx ON {{SCHEMA}}.chunks(content_hash, embedder_version) WHERE embedding IS NOT NULL;
ALTER TABLE {{SCHEMA}}.repos ENABLE ROW LEVEL SECURITY; ALTER TABLE {{SCHEMA}}.files ENABLE ROW LEVEL SECURITY; ALTER TABLE {{SCHEMA}}.chunks ENABLE ROW LEVEL SECURITY;
